input.sparql:
SELECT ?z ?zlabel ?p ?pclass ?tsid WHERE {
  ?brick_uri a brick:Zone .
  FILTER (regex(str(?brick_uri), "Core"))
  ?brick_uri brick:hasPoint ?p .
  ?p rdf:type ?pclass .
  OPTIONAL { ?p ref:hasTimeseriesId ?tsid }
}

